from ext import *
ext('c10_eng_ch16',[
C("📖","कविता की शुरुआत",["कविता मार्था नाम की लड़की पर है","वह हेज़ल के पेड़ों की घाटी में बैठी है","बच्चे उसके चारों ओर इकट्ठा हैं","हर कहानी वन्स अपॉन अ टाइम से शुरू"],"अब कविता को थोड़ा ध्यान से देखते हैं। कविता की शुरुआत में हमें एक सुंदर दृश्य मिलता है। मार्था नाम की एक लड़की हेज़ल के पेड़ों से भरी घाटी में बैठी है। उसके चारों ओर छोटे बच्चे इकट्ठा हैं। सब शांत हैं, क्योंकि मार्था कहानी सुनाने वाली है। कवि ने कोई बड़ी घटना नहीं दिखाई, बस एक साधारण शाम दिखाई है। पर इसी साधारण शाम में जादू छिपा है। जब कहानी शुरू होती है, तो पूरा माहौल बदल जाता है। हवा भी जैसे रुक जाती है और बच्चे आँखें फैलाकर सुनने लगते हैं। यही कविता की सबसे प्यारी बात है।"),
C("🌳","हेज़ल की घाटी का दृश्य",["हेज़ल एक झाड़ीनुमा पेड़ है","डेल यानी पेड़ों से घिरी छोटी घाटी","शांत, छाया वाली और सुंदर जगह","कहानी सुनने के लिए सही माहौल"],"कवि ने जगह का नाम बहुत सोच-समझकर चुना है। हेज़ल एक झाड़ीनुमा पेड़ होता है, और डेल का मतलब है पेड़ों से घिरी छोटी घाटी। सोचिए, ऐसी जगह जहाँ ठंडी छाया हो, पत्तों की सरसराहट हो और कोई शोर न हो। कहानी सुनने के लिए इससे अच्छी जगह और क्या होगी? हमारे गाँव में भी बरगद या पीपल के पेड़ के नीचे बैठकर बुज़ुर्ग कहानियाँ सुनाते थे। कवि हमें याद दिलाते हैं कि कहानी का असली मज़ा खुली, शांत और अपनी जगह में आता है, न कि भागदौड़ में।"),
C("👧","मार्था कौन है",["एक साधारण लड़की, पर कुशल कथावाचक","कल्पना और शब्दों की धनी","बच्चों का ध्यान बाँध लेती है","कविता की मुख्य पात्र"],"अब बात करते हैं मार्था की। मार्था कोई राजकुमारी या जादूगरनी नहीं है। वह एक साधारण लड़की है, पर उसके पास एक बड़ा हुनर है, कहानी सुनाने का हुनर। वह शब्दों से चित्र बना देती है। उसकी आवाज़ में उतार-चढ़ाव है, इसलिए बच्चे उसकी हर बात पर ध्यान देते हैं। परीक्षा में अगर पूछा जाए कि मार्था कौन है, तो लिखिए कि वह इस कविता की मुख्य पात्र है, जो घाटी में बच्चों को कहानियाँ सुनाती है और अपनी कल्पना से उन्हें मंत्रमुग्ध कर देती है।"),
C("👂","बच्चे और उनका ध्यान",["बच्चे चुपचाप सुनते हैं","आँखें खुली, मन कहानी में","स्पेलबाउंड यानी मंत्रमुग्ध","अच्छी कहानी सबको बाँध लेती है"],"कविता में बच्चे भी उतने ही महत्वपूर्ण हैं। वे चुपचाप बैठकर सुनते हैं। उनकी आँखें खुली हैं और मन पूरी तरह कहानी में डूबा है। अंग्रेज़ी में इसके लिए शब्द है स्पेलबाउंड, यानी मंत्रमुग्ध, जैसे किसी जादू ने बाँध लिया हो। आज के समय में बच्चे मोबाइल में खोए रहते हैं, पर पुराने समय में यही जादू कहानियाँ करती थीं। इस कविता से हमें सीख मिलती है कि अच्छी कहानी बिना किसी मशीन के भी बच्चों को घंटों बाँधकर रख सकती है।"),
C("🔁","पुनरावृत्ति की सुंदरता",["वही शब्द बार-बार आते हैं","लय और संगीत पैदा होता है","कहानी का माहौल बनता है","याद रखना आसान हो जाता है"],"इस कविता की एक ख़ास बात है पुनरावृत्ति, यानी एक ही शब्द या वाक्य का बार-बार आना। जैसे हर कहानी वन्स अपॉन अ टाइम से शुरू होती है। इससे कविता में एक लय बनती है, जैसे लोरी में होती है। पुनरावृत्ति से दो फ़ायदे होते हैं। पहला, कविता सुनने में मधुर लगती है। दूसरा, बात मन में बैठ जाती है। परीक्षा में काव्य सौंदर्य लिखते समय पुनरावृत्ति का ज़िक्र ज़रूर कीजिए। यह छोटा सा बिंदु आपको अच्छे अंक दिला सकता है।"),
C("🎨","बिंब यानी इमेजरी",["घाटी, पेड़ और आँखों के चित्र","पढ़ते ही दृश्य सामने आता है","शब्दों से बनी तस्वीर","कविता को जीवंत बनाते हैं"],"कविता की दूसरी ख़ूबी है बिंब, जिसे अंग्रेज़ी में इमेजरी कहते हैं। बिंब का मतलब है शब्दों से ऐसी तस्वीर बनाना कि पढ़ने वाले को दृश्य दिखाई दे। यहाँ हमें हेज़ल के पेड़, शांत घाटी, बच्चों की चमकती आँखें और मार्था का चेहरा, सब कुछ दिखाई देता है। कवि ने रंगों का नहीं, शब्दों का ब्रश इस्तेमाल किया है। जब आप कविता पढ़ें, तो आँखें बंद करके उस दृश्य की कल्पना कीजिए। इससे कविता समझना और याद रखना, दोनों आसान हो जाते हैं।"),
C("✍️","कवि वॉल्टर डी ला मेयर",["इंग्लैंड के कवि और कहानीकार","बच्चों के लिए जादुई कविताएँ","द लिसनर उनकी प्रसिद्ध कविता","सरल शब्द, गहरी कल्पना"],"अब कवि के बारे में थोड़ा और जान लेते हैं। वॉल्टर डी ला मेयर इंग्लैंड के प्रसिद्ध कवि और कहानीकार थे। उन्होंने बच्चों और बड़ों, दोनों के लिए लिखा। उनकी कविताओं में रहस्य और जादू का स्पर्श मिलता है। द लिसनर उनकी बहुत प्रसिद्ध कविता मानी जाती है। उनकी भाषा बहुत सरल होती है, पर कल्पना गहरी होती है। मार्था में भी यही बात दिखती है। साधारण शब्दों में उन्होंने बचपन की कहानियों की पूरी दुनिया समेट दी है। परीक्षा में कवि का परिचय पाँच-छह वाक्यों में लिखना आना चाहिए।"),
C("📚","कहानियों का महत्व",["कल्पना शक्ति बढ़ती है","भाषा और शब्द-भंडार सुधरता है","नैतिक सीख मिलती है","परिवार और समाज से जुड़ाव"],"कहानियाँ सिर्फ़ मनोरंजन नहीं हैं। वे हमारी कल्पना शक्ति को बढ़ाती हैं। कहानी सुनने वाला बच्चा नए शब्द सीखता है और भाषा पर पकड़ मज़बूत करता है। कहानियों से अच्छे-बुरे की समझ भी मिलती है। पंचतंत्र की कहानियाँ इसका अच्छा उदाहरण हैं, जहाँ जानवरों के बहाने जीवन की बड़ी सीख दी जाती है। साथ ही कहानी सुनाने से परिवार के लोग आपस में जुड़ते हैं। दादा-दादी और पोते-पोतियों के बीच का रिश्ता कहानियों से और गहरा हो जाता है।"),
C("📝","शब्दार्थ दोहराइए",["हेज़ल, डेल, चिन","ग्रे, स्पेलबाउंड","टेल, लिसन, सिट","हर शब्द से एक वाक्य बनाइए"],"आइए नए शब्द एक बार फिर दोहरा लें। हेज़ल यानी एक पेड़, डेल यानी छोटी घाटी, ग्रे यानी धूसर रंग, चिन यानी ठोड़ी, और स्पेलबाउंड यानी मंत्रमुग्ध। साथ में टेल यानी सुनाना, लिसन यानी सुनना और सिट यानी बैठना जैसे सरल शब्द भी याद रखिए। एक तरीक़ा आज़माइए। हर शब्द से अपना एक वाक्य बनाइए, जैसे द चिल्ड्रन आर स्पेलबाउंड। जब आप शब्द को वाक्य में इस्तेमाल करते हैं, तो वह हमेशा के लिए याद हो जाता है। सिर्फ़ रटने से शब्द जल्दी भूल जाते हैं।"),
C("🧩","सामान्य भूतकाल दोबारा",["वर्ब की दूसरी रूप: टोल्ड, सैट","नियमित क्रिया में एड जोड़ें","अनियमित क्रिया अलग से याद करें","वाक्य: शी टोल्ड अ स्टोरी"],"कविता में सामान्य भूतकाल का प्रयोग है। जो काम बीत चुका है, उसके लिए क्रिया का दूसरा रूप इस्तेमाल होता है। जैसे टेल का भूतकाल टोल्ड और सिट का भूतकाल सैट है। ये अनियमित क्रियाएँ हैं, इन्हें अलग से याद करना पड़ता है। नियमित क्रियाओं में बस एड जोड़ देते हैं, जैसे लिसन से लिसन्ड। एक अभ्यास कीजिए। पाँच क्रियाएँ चुनिए और उनके भूतकाल रूप लिखिए। फिर हर रूप से एक वाक्य बनाइए। इस तरह व्याकरण कविता से जुड़कर आसान हो जाएगा।"),
C("🏡","हमारी अपनी कहानियाँ",["गाँव की चौपाल की कहानियाँ","दादी-नानी की लोककथाएँ","सामा चकेवा, गोनू झा","इन्हें लिखकर बचाइए"],"मार्था की तरह हमारे यहाँ भी कहानी सुनाने की बहुत पुरानी परंपरा है। बिहार में सामा चकेवा की लोककथा, गोनू झा की चतुराई के क़िस्से और मिथिला की कितनी ही कहानियाँ पीढ़ियों से सुनाई जाती हैं। आज इनमें से कई कहानियाँ भुलाई जा रही हैं। इसलिए एक काम कीजिए। अपनी दादी या नानी से कोई एक कहानी सुनिए और उसे कॉपी में लिख लीजिए। इस तरह आप अपनी विरासत को बचाएँगे और अंग्रेज़ी में लिखने का अभ्यास भी हो जाएगा।"),
C("❓","संभावित परीक्षा प्रश्न",["कविता का कवि कौन है","मार्था कहाँ बैठती है","बच्चे कैसे सुनते हैं","कविता का केंद्रीय भाव लिखिए"],"अब परीक्षा की तैयारी करते हैं। इस कविता से अक्सर ऐसे प्रश्न आते हैं। कविता का कवि कौन है? उत्तर, वॉल्टर डी ला मेयर। मार्था कहाँ बैठती है? उत्तर, हेज़ल के पेड़ों की घाटी में। बच्चे कैसे सुनते हैं? उत्तर, चुपचाप और मंत्रमुग्ध होकर। और अंत में केंद्रीय भाव, यानी कहानियों का जादू और बचपन की कल्पना। उत्तर लिखते समय पूरे वाक्य में लिखिए, एक शब्द का उत्तर मत दीजिए। और जहाँ संभव हो, कविता की एक पंक्ति का ज़िक्र करके अपनी बात को मज़बूत कीजिए।"),
Q("अगर आप मार्था की जगह होते, तो बच्चों को कौन सी कहानी सुनाते और क्यों?","कोई भी कहानी चुनिए, जैसे पंचतंत्र की, और कारण बताइए कि उसमें कौन सी सीख है।","अब आपके लिए एक सोचने वाला प्रश्न। मान लीजिए आप मार्था की जगह हैं। आपके सामने बच्चे बैठे हैं। आप कौन सी कहानी सुनाएँगे और क्यों? कुछ पल रुककर सोचिए। ... कोई भी कहानी चुन सकते हैं, जैसे पंचतंत्र की कोई कथा, और बताइए कि उसमें कौन सी सीख है। जैसे ईमानदारी, मेहनत या दोस्ती। कारण देना सबसे ज़रूरी है, क्योंकि परीक्षा में भी कारण लिखने पर ही पूरे अंक मिलते हैं।"),
Q("कविता में पुनरावृत्ति से क्या लाभ होता है?","इससे कविता में लय आती है और बात याद रखना आसान हो जाता है।","एक और प्रश्न। कविता में पुनरावृत्ति से क्या लाभ होता है? सोचिए। ... उत्तर, पुनरावृत्ति से कविता में लय और मधुरता आती है और बात आसानी से याद रह जाती है। इसके साथ कहानी सुनाने का माहौल भी बनता है। इसे अपनी कॉपी में पूरे वाक्य में लिख लीजिए।"),
],7)
